#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): this feature has no default pins, so installing it
# with its defaults fails by design and this script is not reached there. It
# is kept for a local run that supplies a pin through the image (for example
# `devcontainer features test -f cli-claude-code -i <image with
# CLI_CLAUDE_CODE_* ENV>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=claude-code-checks.sh
source "$(dirname "$0")/claude-code-checks.sh"

check "claude resolves to /usr/local/bin/claude" _claude_is_local_bin
check "claude is mode 0755, owned by root" _claude_mode_owner
check "claude --version runs" claude --version

reportResults
